function Badge({status,late,kind}:{status?:string;late?:boolean;kind?:string}){if(late)return <span className={`badge ${kind==='problems'||kind==='writing'?'late':'revision'}`}>{kind==='problems'||kind==='writing'?'△ 지각 제출 · 성사율 제외':kind==='wake'?'X · 기상 인증 시간 초과':'지각 · 성사율 제외'}</span>;const names:Record<string,string>={approved:'O · 확인 완료',submitted:'확인 대기',revision:'X · 보완 필요',missed:'X · 미완료'};return <span className={`badge ${status??'empty'}`}>{status==='approved'?<Check size={12}/>:status==='submitted'?<Clock size={12}/>:null}{names[status??'']??'진행 전'}</span>;}
