 <div className="stats-grid three"><Stat label="개별진도 완료" value={<>{stats.percent}<em>%</em></>} caption={`${stats.done} / ${stats.total}개 학습 확인`} icon={<TrendingUp size={18}/>}/><Stat label="조교 확인 대기" value={<>{stats.submitted}<em>개</em></>} caption="제출과 확인 완료를 구분해요" icon={<ClipboardCheck size={18}/>}/><Stat label="나의 성장" value={`Lv. ${stats.level}`} caption={stats.level===50?'최종 진화에 도달했어요':`다음 레벨까지 ${stats.nextLevel} XP`} icon={<Sparkles size={18}/>}/></div>
