function LegacySurvey({student:s,act,done}:{student:Student;act:Act;done:()=>void}){
 const readOnly=useGuardianView();
 const [step,setStep]=useState(0),[answers,setAnswers]=useState({...s.answers}),[potential,setPotential]=useState([...s.potential]),[korean,setKorean]=useState(s.korean.join(', ')),[target,setTarget]=useState(s.target),[availability,setAvailability]=useState(s.availability),[books,setBooks]=useState(s.currentBooks),[delay,setDelay]=useState(s.delayReason),[saving,setSaving]=useState(false),[error,setError]=useState('');
 useEffect(()=>{if(readOnly){setAnswers({...s.answers});setPotential([...s.potential]);setKorean(s.korean.join(', '));setTarget(s.target);setAvailability(s.availability);setBooks(s.currentBooks);setDelay(s.delayReason);}},[readOnly,s]);
 const group=GROUPS[step],questions=group?QUESTION_ROWS.filter(q=>q[0].startsWith(group.id)):[],answered=Object.keys(answers).length;
 const save=async(next:boolean)=>{if(readOnly){if(next){if(step<6)setStep(step+1);else done();}return;}setSaving(true);setError('');try{
  if(step===6){if(answered<40)throw new Error('앞 단계에서 답하지 않은 문항을 확인해 주세요. 경험이 없으면 해당 경험 없음을 선택하면 됩니다.');if(![0,1,2,3].every(i=>Number.isInteger(potential[i])))throw new Error('잠재력 보조 항목에 모두 답해 주세요.');const grades=korean.trim()?korean.split(/[ ,·]+/).filter(Boolean).map(Number):[];await act({action:'profile',studentId:s.id,korean:grades,target,availability,currentBooks:books,delayReason:delay});}
  await act({action:'survey',studentId:s.id,answers,potential,completed:step===6});if(next){if(step===6)done();else{setStep(step+1);window.scrollTo({top:0,behavior:'smooth'});}}
 }catch(e){setError(e instanceof Error?e.message:'저장하지 못했습니다.');}finally{setSaving(false);}};
 const options=(kind:string)=>kind==='생각'?['전혀 아니다','별로 아니다','어느 쪽도 아니다','대체로 그렇다','매우 그렇다']:['전혀 없었다','드물게 있었다','절반 정도','대부분 그랬다','거의 항상'];
 return <div className="survey-layout"><section className="card survey-intro"><span className="eyebrow">OMNI MATH DIAGNOSTIC</span><h2>나에게 맞는 학습을 찾는 첫 단계</h2><p>좋아 보이는 답보다 최근의 실제 모습에 가깝게 답해 주세요. 행동은 최근 2주, 시험운용은 최근 최대 3번의 수학 시험을 떠올려 주세요.</p><div className="survey-progress"><span style={{width:`${answered/40*100}%`}}/></div><div className="survey-progress-label"><span>핵심 문항 {answered} / 40</span><strong>{step+1} / 7단계</strong></div></section><div className="survey-step-tabs">{[...GROUPS.map(g=>g.short),'잠재력·정보'].map((t,i)=><button key={t} className={i===step?'active':''} onClick={()=>setStep(i)}>{i+1}. {t}</button>)}</div>
 <fieldset disabled={readOnly}>{group?<section className="card survey-questions"><div className="section-head"><h3>{group.label}</h3><span className="subtle-pill">{questions.length}문항</span></div>{questions.map((q,i)=><div className="question" key={q[0]}><div className="question-title"><span>{String(i+1).padStart(2,'0')}</span><h4>{q[1]}</h4></div><small className="question-kind">{q[2]==='생각'?'현재 생각':q[2]==='시험'?'최근 수학 시험에서':'최근 2주 해당 상황에서'}</small><div className="answer-options" role="group" aria-label={q[1]}>{options(q[2]).map((label,n)=><button key={n} className={answers[q[0]]===n+1?'selected':''} aria-pressed={answers[q[0]]===n+1} onClick={()=>setAnswers({...answers,[q[0]]:n+1})}><span>{n+1}</span>{label}</button>)}</div><button className={`na-answer ${q[0] in answers&&answers[q[0]]===null?'selected':''}`} onClick={()=>setAnswers({...answers,[q[0]]:null})}>해당 경험 없음 / 잘 모르겠음</button></div>)}</section>:<><section className="card survey-questions"><div className="section-head"><h3>성장에 활용할 학습 경험</h3><Sparkles size={22}/></div>{POTENTIAL_QUESTIONS.map((q,i)=><div className="question" key={q}><h4>{i+1}. {q}</h4><div className="answer-options">{options('생각').map((label,n)=><button key={n} className={potential[i]===n+1?'selected':''} onClick={()=>{const p=[...potential];p[i]=n+1;setPotential(p);}}><span>{n+1}</span>{label}</button>)}</div><button className={`na-answer ${potential[i]===0?'selected':''}`} onClick={()=>{const p=[...potential];p[i]=0;setPotential(p);}}>경험 없음 / 잘 모르겠음</button></div>)}</section><section className="card"><h3>실행할 수 있는 계획을 위한 정보</h3><div className="form-grid"><label>최근 국어 등급 · 최대 3회<input value={korean} onChange={e=>setKorean(e.target.value)} placeholder="예: 1, 2, 2 · 없으면 비워두세요"/></label><label>목표 수학 등급<input value={target} onChange={e=>setTarget(e.target.value)}/></label><label className="full">요일별 공부 가능 시간<textarea value={availability} onChange={e=>setAvailability(e.target.value)} placeholder="평일·주말과 학교 등 고정 일정을 적어 주세요"/></label><label>현재 강의·교재<input value={books} onChange={e=>setBooks(e.target.value)} placeholder="사용 중인 자료가 있다면 적어 주세요"/></label><label>과제가 밀리는 주된 이유<select value={delay} onChange={e=>setDelay(e.target.value)}><option value="">선택해 주세요</option>{['지연 없음','시간 부족','문제가 어려움','시작 미룸','완벽히 못 해서 제출 미룸','해야 할 일을 모름','일정 충돌','촬영·업로드 문제'].map(t=><option key={t}>{t}</option>)}</select></label></div></section></>}
 </fieldset>{error&&<div className="notice amber">{error}</div>}<div className="survey-buttons"><button className="secondary" disabled={step===0||saving} onClick={()=>setStep(step-1)}><ArrowLeft size={16}/>이전 단계</button><div className="button-group">{!readOnly&&<button className="text-btn" disabled={saving} onClick={()=>save(false)}>현재 응답 저장</button>}<button className="primary" disabled={saving} onClick={()=>save(true)}>{saving?'저장 중…':step===6?'나의 진단 결과 확인':readOnly?'다음 단계 보기':'저장하고 다음 단계'}<ArrowRight size={17}/></button></div></div></div>;
}
function taskFromId(s:Student,id:string,themes:Theme[]):Task{
 const extra=bookTasks(s).find(t=>t.id===id);if(extra)return extra;
 if(id.startsWith('daily:'))return dailyTasks(s,id.split(':')[1]).find(t=>t.id===id)!;
 if(id.startsWith('attendance:'))return {id,kind:'attendance',label:`Zoom 출석 · ${dateLabel(id.split(':')[1])}`,description:'정해진 수업의 참석 여부',mark:s.marks[id]};
 const theme=themes.find(t=>t.id===id.split(':')[0])??themes.find(t=>t.id==='c-12.2');const task=theme?themeTasks(s,theme).find(t=>t.id===id):null;
 return task??{id,kind:'practice',label:id,description:'과제 기록',mark:s.marks[id]};
}
