function Materials({themes,edit}:{themes:Theme[];edit:(t:Theme)=>void}){
 const [subject,setSubject]=useState('전체');
 return <><div className="notice blue"><BookOpen size={18}/>테마는 과정·번호와 등록된 이름으로 표시합니다. 실제 파일을 등록하기 전에는 안내용 가상 파일이 제공됩니다.</div><section className="card"><div className="section-head"><h3>강의·시험지·연습문제</h3><select aria-label="과정 필터" value={subject} onChange={e=>setSubject(e.target.value)}><option>전체</option>{[...new Set(themes.map(t=>t.subject))].map(t=><option key={t}>{t}</option>)}</select></div><div className="table-scroll"><table className="roster-table material-table"><thead><tr><th>테마</th><th>예상 시간</th><th>강의</th><th>시험지</th><th>연습문제</th><th/></tr></thead><tbody>{themes.filter(t=>subject==='전체'||t.subject===subject).map(t=><tr key={t.id}><td><strong>{t.title||`Theme ${t.number}`}</strong><small>{t.subject}{t.title?` · Theme ${t.number}`:''}</small></td><td>{t.minutes}분</td><td><span className={`status-dot ${t.lectureUrl?'ready':''}`}/>{t.lectureUrl?'등록됨':'준비 중'}</td><td><MaterialLink theme={t} kind="test"/></td><td>{t.practice?<MaterialLink theme={t} kind="practice"/>:<span className="muted">없음</span>}</td><td><button className="secondary small-btn" onClick={()=>edit(t)}><Settings2 size={14}/>설정</button></td></tr>)}</tbody></table></div></section></>;
}
function MaterialForm({theme:t,act,done}:{theme:Theme;act:Act;done:()=>void}){
 const [title,setTitle]=useState(t.title??''),[url,setUrl]=useState(t.lectureUrl??''),[minutes,setMinutes]=useState(t.minutes),[practice,setPractice]=useState(t.practice),[testFile,setTestFile]=useState<File|null>(null),[practiceFile,setPracticeFile]=useState<File|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 return <><p className="section-intro">필기 범위는 인강에 나오는 선생님 손필기 전부입니다.{t.id==='c-12'||t.id==='c-12.2'?' Theme 12·12.2의 연습문제 파일은 함께 적용됩니다.':''}</p><div className="form-grid"><label className="full">테마 이름<input value={title} onChange={e=>setTitle(e.target.value)} maxLength={80} placeholder="예: 이차방정식 · 실제 테마 이름을 입력하세요"/></label><label className="full">인강 주소<input type="url" value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://…"/></label><label>예상 학습 시간<input type="number" min="30" max="60" value={minutes} onChange={e=>setMinutes(Number(e.target.value))}/><small>30~60분</small></label><label>연습문제 유무<select value={practice?'yes':'no'} onChange={e=>setPractice(e.target.value==='yes')}><option value="yes">있음 · 제출 확인</option><option value="no">없음 · 과제에서 제외</option></select></label><label className="full">시험지 파일{t.testFile&&<small>현재: {t.testFile.name}</small>}<input type="file" accept="application/pdf,image/png,image/jpeg,.docx,text/plain" onChange={e=>setTestFile(e.target.files?.[0]??null)}/></label>{practice&&<label className="full">연습문제 파일{t.practiceFile&&<small>현재: {t.practiceFile.name}</small>}<input type="file" accept="application/pdf,image/png,image/jpeg,.docx,text/plain" onChange={e=>setPracticeFile(e.target.files?.[0]??null)}/></label>}</div>{error&&<div className="notice amber">{error}</div>}<div className="modal-actions"><button className="primary" disabled={busy} onClick={async()=>{setBusy(true);setError('');try{const test=testFile?(await uploadFiles([testFile],'material',undefined,t.id))[0]:undefined,exercise=practiceFile?(await uploadFiles([practiceFile],'material',undefined,t.id))[0]:undefined;await act({action:'material',themeId:t.id,title,lectureUrl:url,minutes,practice,testFile:test,practiceFile:exercise});done();}catch(e){setError(e instanceof Error?e.message:'저장하지 못했습니다.');}finally{setBusy(false);}}}><Check size={17}/>{busy?'업로드·저장 중…':'자료 설정 저장'}</button></div></>;
}
